import { json } from '@sveltejs/kit';
import { z } from 'zod';
import { apiError, getSupabaseAdmin, requireRole, writeAudit } from '$lib/server/supabase';
const schema=z.object({mode:z.enum(['draft','review'])});
async function exists(bucket:string,path:string){const admin=getSupabaseAdmin();const parts=path.split('/');const name=parts.pop()!;const folder=parts.join('/');const {data,error}=await admin.storage.from(bucket).list(folder,{limit:10,search:name});if(error)throw error;return Boolean(data?.some(item=>item.name===name));}
export async function POST({locals,request,params}:import('./$types').RequestEvent){try{const {user}=await requireRole(locals,['vendor']);const body=schema.parse(await request.json());const admin=getSupabaseAdmin();const {data:vendor}=await admin.from('vendor_profiles').select('id').eq('user_id',user.id).single();const {data:product}=await admin.from('products').select(`id,title,slug,versions:product_versions(id,package_path,documentation_path,created_at),images:product_images(storage_path)`).eq('vendor_id',vendor.id).eq('slug',params.slug).single();if(!product)return json({message:'Product draft not found.'},{status:404});const version=[...((product.versions as any[])??[])].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))[0];if(!version||!(await exists('asset-packages',version.package_path)))return json({message:'The asset package upload did not complete.'},{status:409});if(version.documentation_path&&!(await exists('asset-packages',version.documentation_path)))return json({message:'The documentation upload did not complete.'},{status:409});for(const image of (product.images as any[])??[])if(!(await exists('product-images',image.storage_path)))return json({message:'One or more preview uploads did not complete.'},{status:409});const next=body.mode==='review'?'in_review':'draft';await admin.from('products').update({status:next}).eq('id',product.id);await writeAudit({actorId:user.id,actorRole:'vendor',action:body.mode==='review'?'product.submitted_for_review':'product.draft_saved',entityType:'product',entityId:product.id,request});return json({ok:true,status:next});}catch(error){console.error(error);const e=apiError(error);return json({message:error instanceof z.ZodError?'Invalid completion request.':e.message},{status:error instanceof z.ZodError?400:e.status});}}
